// Fail-closed auth, same contract as every other VIO webhook. This one matters more than most:
// it is the only online route that can put an email in front of a real stranger. A forged call
// here spends the company's reputation, not just its credits.
//
// Authentication is NOT the approval gate — it only decides who may *propose*. Even a caller
// holding the right token cannot enrol anyone; they can only cause a human to be asked.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// Build the enrolment proposal a human is asked to authorise — and nothing else. This node makes
// no network call. It decides who WOULD be contacted, freezes the exact request bodies, and states
// all of it in language a person can judge.
//
// Everything after the gate reads its lead list back out of THIS node (`$('Build Proposal')`), never
// out of the approval reply. So an approval authorises exactly the list that was displayed: the
// Slack round-trip cannot add a recipient, swap a campaign, or edit an opener.

// ---------------------------------------------------------------------------------------------
// HARD CAP: 12 leads per approved call.
//
//  1. The human has to be able to read every address. The ask_human tool truncates its `detail`
//     field at 1500 characters. Twelve fully-rendered recipient lines always fit; forty do not,
//     and a truncated list means the human approves a prefix while the workflow enrols the whole
//     thing. The invariant is asserted below, not assumed — if any address would fall outside the
//     visible text this node REFUSES rather than asks.
//  2. Twelve strangers is a batch a person can actually check, name by name. "Approve 200 leads"
//     is a rubber stamp with a number on it.
//  3. A bigger send should be a deliberate sequence of separately-approved batches, so that one
//     mistaken click cannot mail an entire list.
//
// Over the cap is a REFUSAL, never a silent truncation: truncating would enrol a different set
// than the caller described, and the human would be approving a list nobody proposed.
const MAX_LEADS = 12;

// ---------------------------------------------------------------------------------------------
// CAMPAIGN ALLOW-LIST. This is a SHARED Instantly workspace holding ~12 unrelated live campaigns
// belonging to other clients (INTEGRATIONS.md: "Do not touch any existing campaign this build
// didn't create"). A free-text campaign id supplied by an LLM could drop our prospects into
// someone else's sequence, or drop someone else's prospects into ours. So the caller names a
// PRODUCT and the id comes from here; an unknown product is refused before a human is even asked,
// exactly the way VIO-sendr-generate-page and VIO-source-leads fail closed.
const CAMPAIGNS = {
  oryoniq: {
    id: '77b2cd80-5bf2-4656-8857-b310858d5a77',
    name: 'OryonIQ - Reach Engine Pilot (2026-08)',
    // Whose copy this campaign carries. Not always the same as the allow-list key: the demo
    // campaign is keyed 'demo' but sends OryonIQ's step-1 body verbatim, so a row enrolled
    // through it was pitched BY OryonIQ and must say so.
    product: 'oryoniq',
  },
  // VisioneerIT has a Sendr LinkedIn sequence (10751) but no Instantly campaign has been created
  // for it yet. Listed as null so the refusal says WHY instead of "unknown product".
  visioneerit: null,
  // Added 2026-08-22 for a live end-to-end test to a known internal address. Separate from
  // the OryonIQ pilot on purpose: it carries an always-on send window (the pilot is
  // 09:00-17:00 Mon-Fri Detroit, and the test ran on a Saturday), so the real campaign's
  // schedule was never touched. Same step-1 body, verbatim.
  demo: {
    id: '0525f568-6f2f-4fca-8f97-16552d7c20f6',
    name: 'VIO - Live Demo (2026-08-22)',
    product: 'oryoniq',
  },
};

const raw = $input.first().json || {};
// toolWorkflow hands the agent's arguments over as { query: {...} }; the webhook path hands the
// body straight through. Accept both, prefer neither.
const q = (raw.query && typeof raw.query === 'object' && !Array.isArray(raw.query)) ? raw.query : raw;

// Require a STRING. String(['oryoniq']) === 'oryoniq', so coercing here would let an array — or
// anything with a convenient toString — through a gate whose entire job is to refuse the unknown.
if (typeof q.product !== 'string') {
  throw new Error(`REFUSED: 'product' must be a string, got ${Array.isArray(q.product) ? 'array' : typeof q.product}`);
}
const key = q.product.trim().toLowerCase();
if (!Object.prototype.hasOwnProperty.call(CAMPAIGNS, key)) {
  throw new Error(`REFUSED: unknown product '${q.product}'. Known: ${Object.keys(CAMPAIGNS).join(', ')}`);
}
const campaign = CAMPAIGNS[key];
if (!campaign) {
  throw new Error(`REFUSED: '${key}' has no Instantly campaign yet, so there is nothing to enrol into. Create one, then add its id to this node.`);
}
// If the caller ALSO names a campaign id it must match the allow-list. A disagreement is refused
// rather than resolved: one of the two is wrong, and guessing which would pick a campaign that
// nobody actually chose.
if (q.campaign !== undefined && q.campaign !== null && q.campaign !== '') {
  if (typeof q.campaign !== 'string' || q.campaign.trim() !== campaign.id) {
    throw new Error(`REFUSED: campaign '${q.campaign}' is not the ${key} campaign (${campaign.id}).`);
  }
}

// RE-CONTACT. `skip_if_in_campaign: true` is the safe default and matches across the WHOLE
// workspace, not just the target campaign — so anyone already sitting in any other sequence is
// skipped, and Instantly still returns 200 with the pre-existing record's id (verified live
// 2026-08-22). Overriding that means deliberately mailing someone who is already in a sequence,
// which is a decision a human must make knowingly, so it is opt-in AND stated in the proposal.
const allowRecontact = q.allow_recontact === true;

if (!Array.isArray(q.leads)) {
  throw new Error(`REFUSED: 'leads' must be an array, got ${typeof q.leads}`);
}
const leadsIn = q.leads;
if (leadsIn.length === 0) throw new Error('REFUSED: no leads supplied — nothing to propose.');
if (leadsIn.length > MAX_LEADS) {
  throw new Error(`REFUSED: ${leadsIn.length} leads exceeds the per-approval cap of ${MAX_LEADS}. Split it into batches and get each batch approved on its own.`);
}

const clean = (v, cap) => (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, cap) : '');
// Deliberately strict. An address that does not look like one address is not enrolled: a comma or
// an angle bracket smuggled into this field is how one lead record becomes two recipients.
const EMAIL = /^[^\s@,;<>"]+@[^\s@,;<>"]+\.[^\s@,;<>"]+$/;

const eligible = [];
const skipped = [];
const seen = new Set();

for (const lead of leadsIn) {
  const l = (lead && typeof lead === 'object' && !Array.isArray(lead)) ? lead : {};
  const email = clean(l.contact_email, 160).toLowerCase();
  const who = clean(l.first_name, 80) || email || '(unnamed lead)';

  // The same three skips as push_to_instantly.py, in the same order, for the same reasons.
  if (!email || !EMAIL.test(email)) {
    skipped.push({ who, why: 'no usable contact_email — revealing and verifying an address is a separate, earlier step' });
    continue;
  }
  if (l.verify_action === 'drop') {
    skipped.push({ who, why: 'verify hard-dropped this address' });
    continue;
  }
  const page = clean(l.sendr_page_url, 500);
  if (!page) {
    // push_to_instantly.py has an override flag for this, off by default; this workflow has no
    // equivalent at all, on purpose. The campaign CTA links to {{sendrPageUrl}} and Instantly
    // renders an unknown tag as an empty string, so a lead without a page receives a sentence
    // that ends in a bare colon. Generate the page first. The test asserts that no override
    // exists anywhere in this file.
    skipped.push({ who, why: 'no sendr_page_url — the campaign CTA is {{sendrPageUrl}}, and Instantly renders an unknown tag as an empty string, so this person would get a sentence ending in a bare colon' });
    continue;
  }
  if (seen.has(email)) {
    skipped.push({ who, why: 'duplicate address inside this batch' });
    continue;
  }
  seen.add(email);
  eligible.push({
    email,
    first_name: clean(l.first_name, 80),
    company: clean(l.company, 160),
    title: clean(l.title, 120),
    opener: clean(l.opener, 1200),
    sendr_page_url: page,
  });
}

if (eligible.length === 0) {
  throw new Error(`REFUSED: none of the ${leadsIn.length} supplied lead(s) are enrollable — ${skipped.map((s) => `${s.who}: ${s.why}`).join(' | ')}. Not asking a human to approve an empty send.`);
}

// The exact request bodies, frozen BEFORE anyone is asked. What is approved is what is sent.
const bodies = eligible.map((l) => {
  const body = {
    campaign: campaign.id,
    email: l.email,
    first_name: l.first_name || null,
    company_name: l.company || null,
    job_title: l.title || null,
    personalization: l.opener || null,
    skip_if_in_campaign: !allowRecontact,
  };
  // TOP-LEVEL, and never nested. Instantly merges `custom_variables` into the lead's stored
  // payload, where the template reads {{sendrPageUrl}}. Sending the identical key inside a
  // `payload` object instead returns 201 and SILENTLY DISCARDS it — verified against the live
  // API. Same failure shape as n8n's inert parameters.text: success response, ignored field.
  // There is deliberately no `payload` key on this object at all.
  body.custom_variables = { sendrPageUrl: l.sendr_page_url };
  return body;
});

// ---------------------------------------------------------------------------------------------
// What the human sees. They are authorising contact with real people, so the message names the
// campaign, the exact count, and every individual address. Approving "12 leads" without seeing
// who those twelve are is not informed consent.
const DETAIL_CAP = 1500;   // ask_human's Shape Proposal slices `detail` at 1500 characters.
const short = (s, n) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
const recontactWarning = allowRecontact
  ? '\n\n:warning: RE-CONTACT IS ON. Normally anyone already in another Instantly sequence is '
  + 'skipped. You are choosing to mail them anyway, which can mean a second cold email from a '
  + 'different campaign. Decline if that is not what you meant.'
  : '';
const head = 'Enrolling adds these people to a PAUSED campaign. It does not send. Starting the sequence '
  + "is a separate human action in Instantly's own UI, and this tool cannot perform it.\n\n"
  + `Campaign: ${campaign.name} (${campaign.id})\n`
  + `Recipients (${eligible.length}) — every one of these is a real person who will receive mail once you start the campaign:\n`;
const tail = skipped.length
  ? `\n\nAlso supplied but NOT being enrolled (${skipped.length}): ${skipped.map((s) => `${s.who} — ${s.why}`).join('; ')}`
  : '';

let recipients = eligible
  .map((l, i) => `${i + 1}. ${short(l.first_name || '(no name)', 30)} <${l.email}> — ${short(l.company || '(no company)', 40)}`)
  .join('\n');
let detail = head + recipients + tail + recontactWarning;

if (detail.length > DETAIL_CAP) {
  // Never drop an address to make it fit. Drop the decoration instead — the addresses are the
  // thing being consented to; the company names are context.
  recipients = eligible.map((l, i) => `${i + 1}. <${l.email}>`).join('\n');
  detail = head + recipients + recontactWarning + (skipped.length ? `\n\n(${skipped.length} other supplied lead(s) were skipped — see the tool output.)` : '');
}

// INVARIANT, asserted rather than assumed: a human cannot consent to a recipient they were never
// shown. If the message would be truncated, or an address failed to render into it, refuse — do
// not ask, and do not enrol.
if (detail.length > DETAIL_CAP) {
  throw new Error(`REFUSED: the approval message is ${detail.length} characters and would be truncated at ${DETAIL_CAP}, hiding recipients from the person approving them. Send a smaller batch.`);
}
for (const l of eligible) {
  if (!detail.includes(l.email)) {
    throw new Error(`REFUSED: ${l.email} would not be visible in the approval message. Nobody gets contacted who was not shown.`);
  }
}

const people = eligible.length === 1 ? 'person' : 'people';

return [{ json: {
  // --- the four fields ask_human's Shape Proposal reads ---
  action: `Enrol ${eligible.length} lead(s) into the Instantly email campaign "${campaign.name}"${allowRecontact ? " [RE-CONTACT ON]" : ""}`,
  detail,
  cost: `No API credits. The real cost is first contact with ${eligible.length} real ${people}: once the campaign is started they receive a cold email, and that cannot be taken back.`,
  touches: `${eligible.length} real ${people} at ${new Set(eligible.map((l) => l.company || '(unknown company)')).size} organisation(s). Every recipient address is listed in full in the message body below.`,
  prior_feedback: typeof q.prior_feedback === 'string' ? q.prior_feedback.slice(0, 1000) : '',

  // --- our own state. Not shown to Slack, and never read back from it. ---
  product: key,
  product_copy: campaign.product || key,
  campaign_id: campaign.id,
  campaign_name: campaign.name,
  eligible_count: eligible.length,
  emails: eligible.map((l) => l.email),
  bodies,
  skipped,
  skipped_count: skipped.length,
  max_leads: MAX_LEADS,
  allow_recontact: allowRecontact,
} }];

// FAIL CLOSED, and NARROW.
//
// The approval tool has a single exit node that returns two independent facts: `approved` (a
// boolean) and `outcome` (the label that same node agreed on). Both must line up here. Written as
// `=== true` and `=== 'approve'` on purpose — anything else (a missing field, the string 'true', a
// payload shape changed by a future n8n upgrade) reads as DENIED rather than as a coercible
// truthy value. `!!j.approved` would be right only by luck.
//
// This deliberately does NOT go hunting for `approved` inside nested objects the way the ask_human
// tool tolerates `data.approved` from Slack. Widening the set of places an approval may arrive
// from is the single change most likely to open this gate, so the only accepted location is the
// top level of the approval tool's own exit.
const j = $input.item.json || {};
const approved = j.approved === true && j.outcome === 'approve';
const outcome = approved ? 'approve' : (j.outcome === 'adjust' ? 'adjust' : 'deny');

return { json: {
  approved,
  outcome,
  reason: approved
    ? String(j.reason || 'human approved in Slack')
    : `not approved (approved=${JSON.stringify(j.approved)}, outcome=${JSON.stringify(j.outcome)}) — treated as DENIED`,
  feedback: (outcome === 'adjust' && typeof j.feedback === 'string') ? j.feedback.slice(0, 1000) : '',
  decided_at: String(j.decided_at || new Date().toISOString()),
} };

// THE GATE ITSELF. Four independent properties make it impossible to reach Instantly without a
// boolean-true approval. They do not depend on each other, so breaking one does not open the door.
//
// 1. THIS NODE THROWS. It re-checks the decision rather than trusting that the IF node routed it
//    here. A rewire that fed the rejection branch into this node aborts the whole execution right
//    here, before any HTTP node runs. Position in the graph is not treated as evidence.
//
// 2. THE REQUEST IS BUILT HERE, NOT IN THE HTTP NODE. The enrolment node has no URL of its own and
//    no campaign of its own: its url is `={{ $json.instantly_url }}` and its body is
//    `={{ JSON.stringify($json.instantly_body) }}` — values that exist ONLY in this node's output,
//    and only once the throw above has been passed. The Instantly endpoint string appears exactly
//    once in this entire workflow: below, on the far side of the check. Bypassing the gate does not
//    produce an unapproved call; it produces an HTTP node with nothing to call.
//
// 3. THE LIST IS RE-READ FROM `Build Proposal`, never from the approval reply. The bodies were
//    frozen before the human saw them, and every address in them is re-checked here against the
//    text that was actually displayed. Nothing that came back through Slack can add a recipient.
//
// 4. THERE IS NO CAMPAIGN ENDPOINT ANYWHERE. The only URL this workflow can produce creates lead
//    records inside an existing campaign. Mirroring push_to_instantly.py, which contains no
//    activation call at all, there is no flag, branch or parameter here that could start a send.
const decision = $input.first().json || {};
if (decision.approved !== true || decision.outcome !== 'approve') {
  throw new Error(`REFUSED: reached the enrolment step without an approval (approved=${JSON.stringify(decision.approved)}, outcome=${JSON.stringify(decision.outcome)}). Nothing was sent.`);
}

const proposal = $('Build Proposal').first().json || {};
const bodies = Array.isArray(proposal.bodies) ? proposal.bodies : [];
if (bodies.length === 0) {
  throw new Error('REFUSED: the approved proposal carries no lead bodies.');
}

// The cap is restated rather than imported: n8n Code nodes share no scope, and a cap that only
// exists at proposal time is a cap that a rewire can skip past.
const MAX_LEADS = 12;
if (bodies.length > MAX_LEADS) {
  throw new Error(`REFUSED: ${bodies.length} lead bodies exceeds the per-approval cap of ${MAX_LEADS}.`);
}

// Consent is per-recipient, not per-count. Every address about to be contacted must appear in the
// text the human actually read. This is what makes "Approve" mean "approve these people" instead
// of "approve a number".
const shown = String(proposal.detail || '');
const approvedCampaign = String(proposal.campaign_id || '');
if (!approvedCampaign) throw new Error('REFUSED: the approved proposal names no campaign.');

for (const b of bodies) {
  if (!b || typeof b !== 'object') throw new Error('REFUSED: a lead body is not an object.');
  if (typeof b.email !== 'string' || !b.email) throw new Error('REFUSED: a lead body carries no email address.');
  if (!shown.includes(b.email)) {
    throw new Error(`REFUSED: ${b.email} never appeared in the approval message. Not contacting anyone the human did not see.`);
  }
  if (b.campaign !== approvedCampaign) {
    throw new Error(`REFUSED: the body for ${b.email} targets a campaign other than the approved one.`);
  }
  if (Object.prototype.hasOwnProperty.call(b, 'payload')) {
    throw new Error(`REFUSED: the body for ${b.email} carries a 'payload' key. Instantly silently discards custom variables nested there and answers 201 anyway; they belong at top-level custom_variables.`);
  }
  const cv = b.custom_variables;
  if (!cv || typeof cv !== 'object' || typeof cv.sendrPageUrl !== 'string' || !cv.sendrPageUrl) {
    throw new Error(`REFUSED: ${b.email} has no top-level custom_variables.sendrPageUrl. The campaign CTA would render as a bare colon.`);
  }
  // skip_if_in_campaign guards against mailing someone already in a sequence. It may be false
  // ONLY on a deliberate re-contact — and "deliberate" means the human READ that it was on, not
  // that the caller asked for it. So the permission is taken from the approved proposal AND from
  // the text that was actually displayed, never from the request.
  //
  // (This assertion is why the first re-contact attempt refused: Build Proposal had learned about
  // allow_recontact and this node had not. Defence in depth is only useful if each layer is
  // updated deliberately — which is the point, not an inconvenience.)
  if (b.skip_if_in_campaign === false) {
    if (proposal.allow_recontact !== true) {
      throw new Error(`REFUSED: the body for ${b.email} disables skip_if_in_campaign but the approved proposal did not request re-contact.`);
    }
    if (!/RE-CONTACT IS ON/i.test(String(proposal.detail || ''))) {
      throw new Error(`REFUSED: re-contact is set for ${b.email}, but the approval text the human read did not say so. Nobody may be re-contacted on a warning that was never shown.`);
    }
  } else if (b.skip_if_in_campaign !== true) {
    throw new Error(`REFUSED: the body for ${b.email} does not set skip_if_in_campaign, so an already-enrolled prospect could be mailed twice.`);
  }
}

// The one and only Instantly endpoint this workflow knows. It creates lead records inside an
// existing campaign; it starts nothing.
const INSTANTLY_LEADS_URL = 'https://api.instantly.ai/api/v2/leads';

return bodies.map((body, i) => ({ json: {
  instantly_url: INSTANTLY_LEADS_URL,
  instantly_body: body,
  email: body.email,
  index: i,
  campaign_id: approvedCampaign,
  approved_at: String(decision.decided_at || ''),
} }));

// Report what actually happened, and restate the boundary in the output itself — whoever reads
// this should not have to infer what did and did not happen.
//
// Strings are control-character scrubbed: n8n's lastNode response serialises with RAW control
// characters, which strict JSON parsers reject (found live 2026-08-16).
const scrub = (v) => Array.isArray(v) ? v.map(scrub)
  : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, scrub(x)]))
  : (typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]+/g, ' ') : v);

const p = $('Build Proposal').first().json || {};
const authorized = $('Authorize Enrolment (fail closed)').all().map((i) => i.json || {});
const results = $input.all().map((i) => i.json || {});

let enrolled = 0;
let failed = 0;
let notEnrolled = 0;   // 200 came back, but the lead did not join THIS campaign
const leads = authorized.map((a, i) => {
  const r = results[i] || {};
  if (r.error !== undefined && r.error !== null) {
    failed++;
    return { email: a.email, status: 'failed', detail: String(typeof r.error === 'string' ? r.error : JSON.stringify(r.error)).slice(0, 300) };
  }
  // A 200 with a lead id is NOT evidence the lead joined THIS campaign.
  //
  // `skip_if_in_campaign: true` matches across the WHOLE WORKSPACE, not just the target campaign.
  // When it matches, Instantly returns 200 with the id of the PRE-EXISTING record — still
  // attached to whatever campaign it was already in — and creates nothing. Verified live
  // 2026-08-22: the same address returned id A / campaign 77b2cd80 (an old campaign) with
  // skip=true, and a NEW id / the target campaign with skip=false.
  //
  // Counting those as enrolments is how this workflow reported `enrolled: 2` while the target
  // campaign held zero leads. The response's own `campaign` field is the only proof.
  const landedIn = String(r.campaign || '');
  if (landedIn && p.campaign_id && landedIn !== p.campaign_id) {
    notEnrolled++;
    return { email: a.email, status: 'already_in_another_campaign',
             instantly_lead_id: String(r.id || ''), campaign_on_record: landedIn,
             detail: 'skip_if_in_campaign matched an existing record elsewhere in the workspace, '
                   + 'so nothing was added to the target campaign. Re-contacting someone already '
                   + 'in another sequence is a deliberate decision — ask for it explicitly.' };
  }
  if (!landedIn) {
    notEnrolled++;
    return { email: a.email, status: 'unverified',
             instantly_lead_id: String(r.id || ''),
             detail: 'Instantly returned no campaign on the created record, so this enrolment '
                   + 'could not be confirmed. Treated as NOT enrolled rather than assumed.' };
  }
  enrolled++;
  return { email: a.email, status: 'enrolled', instantly_lead_id: String(r.id || ''),
           campaign_on_record: landedIn };
});

return [{ json: scrub({
  ok: failed === 0 && notEnrolled === 0,
  approved: true,
  outcome: 'approve',
  campaign_id: p.campaign_id || '',
  campaign_name: p.campaign_name || '',
  enrolled,
  failed,
  not_enrolled: notEnrolled,
  enrolled_verified: 'Counted only where Instantly\'s response says the record is on THIS campaign. A 200 alone is not evidence — see the comment in this node.',
  skipped: p.skipped_count || 0,
  skipped_detail: Array.isArray(p.skipped) ? p.skipped : [],
  leads,
  note: 'Enrolment only. The campaign was not started and this workflow cannot start one: it makes '
      + 'exactly one kind of outbound call, a POST that creates lead records, and no campaign '
      + "endpoint is reachable from any node in it. Starting the sequence is a separate human "
      + "action in Instantly's own UI.",
}) }];

// NOT-APPROVED TERMINUS. Reached on the IF node's false output, and it goes nowhere: nothing is
// wired downstream of this node, so this branch is not "an idle false branch next to a send" —
// it is the end of the graph.
const p = $('Build Proposal').first().json || {};
const d = $input.first().json || {};

return [{ json: {
  ok: true,
  approved: false,
  outcome: d.outcome || 'deny',
  enrolled: 0,
  failed: 0,
  reason: String(d.reason || 'no approval recorded — treated as DENIED'),
  feedback: String(d.feedback || ''),
  campaign_id: p.campaign_id || '',
  campaign_name: p.campaign_name || '',
  proposed_count: p.eligible_count || 0,
  proposed_emails: Array.isArray(p.emails) ? p.emails : [],
  next: d.outcome === 'adjust'
    ? 'NOT APPROVED. The human rejected this and gave an adjustment instead. Revise the batch, then call this tool again with the revised list — it will ask for a fresh approval. You hold no approval and nothing has been sent.'
    : 'DENIED. Nothing was sent. Do not re-ask for the same batch. Log the reason and report it.',
  note: 'No lead record was created in Instantly. No email was sent. The campaign was not touched.',
} }];

// Turn the enrolment result into Sheet rows — so a contacted person is recorded in OUR system,
// not only inside Instantly. Until now a send left no trace anywhere: two people were contacted
// tonight and neither `Leads` nor `Events` knew.
//
// ONLY leads whose record actually landed on this campaign are written. A lead that Instantly
// skipped (already in another campaign) was NOT contacted, and writing it as contacted would put
// a false fact into the audit log — worse than no log at all.

function sha256hex(msg) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
