const rep = $input.first().json || {};
const leads = Array.isArray(rep.leads) ? rep.leads : [];
const p = $('Build Proposal').first().json || {};
const bodies = Array.isArray(p.bodies) ? p.bodies : [];
const now = new Date().toISOString();

// Same lead_id rule as VIO-intake-verify-curate's Normalize Lead, so a row written here and a row
// written there are the SAME row: apollo person id when present, else sha256(lowercased email)
// truncated to 16 hex. Recomputed rather than passed, so it cannot drift.
const leadId = (email, apolloId) => apolloId || (email ? sha256hex(String(email).trim().toLowerCase()).slice(0, 16) : '');

const out = [];
for (const l of leads) {
  if (l.status !== 'enrolled') continue;              // not contacted -> not logged as contacted
  const body = bodies.find((b) => b && b.email === l.email) || {};
  const id = leadId(l.email, body.apollo_id);
  out.push({ json: {
    _kind: 'lead',
    lead_id: id,
    source_config: p.product || '',
    product: p.product_copy || p.product || '',
    first_name: body.first_name || '',
    title: body.job_title || '',
    company: body.company_name || '',
    contact_email: l.email,
    opener: body.personalization || '',
    sendr_page_url: (body.custom_variables || {}).sendrPageUrl || '',
    // Enrolled is NOT sent. The campaign may be paused, and starting it is a separate human act,
    // so the honest state is `queued`.
    channel_state_email: 'queued',
    updated_at: now,
  }});
  out.push({ json: {
    _kind: 'event',
    timestamp: now,
    lead_id: id,
    lead_email: l.email,
    tool: 'instantly',
    action: 'enroll',
    units: 1,
    est_cost_usd: '',        // measure, don't estimate — enrolment itself bills nothing
    result: `enrolled into ${p.campaign_name || p.campaign_id || 'campaign'}${p.allow_recontact ? ' (re-contact)' : ''}`,
    workflow: 'VIO-agent-tool-push-instantly',
    source_config: p.product || '',
  }});
}
return out;
